# owner: platform
import unittest
from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError

def make(last, first):
    return Student("1", last, first, "A")

CLASS = [
    make("Halloway", "Juno"),
    make("Dunmere", "Piet"),
    make("Abbot", "Zed"),
]

class SeatingTests(unittest.TestCase):
    # ---
    def test_sorted_and_split(self):
        lines = seat_rows(CLASS, 2)
        self.assertEqual(lines, [
            "Row 1: Abbot, Zed | Dunmere, Piet",
            "Row 2: Halloway, Juno",
        ])

    # ---
    def test_single_row(self):
        lines = seat_rows(CLASS, 10)
        self.assertEqual(len(lines), 1)

    # ---
    def test_bad_seat_count(self):
        for count in (0, -3):
            with self.assertRaises(ProjectError):
                seat_rows(CLASS, count)

    # ---
    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)

if __name__ == "__main__":
    unittest.main()
